using System.Reflection;

using FluentAssertions;
using Microsoft.AspNetCore.Authorization;

using Forge.Api.Controllers;

namespace Forge.Tests.Authorization;

/// <summary>
/// Who may call the quality-engineering endpoints: the recall preview follows recall initiation, the ECO impact
/// follows ECO reads, certificates of analysis are generated by quality and attached by shipping, and the
/// current work instructions are open to the shop floor.
/// </summary>
public sealed class QualityEngineeringRoleTests
{
    private static readonly string[] AllRoles =
    [
        "Admin", "Manager", "Engineer", "PM", "ProductionWorker", "OfficeManager",
        "Controller", "Procurement", "ComplianceOfficer",
    ];

    private static HashSet<string> EffectiveRoles(Type controller, string actionName)
    {
        var action = controller.GetMethod(actionName)!;
        var allowed = new HashSet<string>(AllRoles, StringComparer.Ordinal);
        var attributes = controller.GetCustomAttributes<AuthorizeAttribute>()
            .Concat(action.GetCustomAttributes<AuthorizeAttribute>());
        foreach (var attribute in attributes.Where(a => !string.IsNullOrEmpty(a.Roles)))
            allowed.IntersectWith(attribute.Roles!.Split(',').Select(r => r.Trim()));
        return allowed;
    }

    [Fact]
    public void Recall_preview_follows_recall_initiation()
    {
        var preview = EffectiveRoles(typeof(RecallsController), nameof(RecallsController.Preview));

        preview.Should().BeEquivalentTo(EffectiveRoles(typeof(RecallsController), nameof(RecallsController.Initiate)));
        preview.Should().BeEquivalentTo(["Admin", "Manager"]);
    }

    [Fact]
    public void Eco_impact_follows_eco_reads()
    {
        var impact = EffectiveRoles(typeof(QualityController), nameof(QualityController.GetEcoImpact));

        impact.Should().BeEquivalentTo(EffectiveRoles(typeof(QualityController), nameof(QualityController.GetEcoById)));
        impact.Should().NotContain(["PM", "ProductionWorker", "OfficeManager"]);
    }

    [Fact]
    public void Certificates_are_generated_and_voided_by_quality()
    {
        EffectiveRoles(typeof(CertificatesOfAnalysisController), nameof(CertificatesOfAnalysisController.Generate))
            .Should().BeEquivalentTo(["Admin", "Manager", "Engineer"]);
        EffectiveRoles(typeof(CertificatesOfAnalysisController), nameof(CertificatesOfAnalysisController.Void))
            .Should().BeEquivalentTo(["Admin", "Manager", "Engineer"]);
    }

    [Fact]
    public void Certificates_are_attached_to_shipments_by_the_shipment_roles()
    {
        EffectiveRoles(typeof(CertificatesOfAnalysisController), nameof(CertificatesOfAnalysisController.AttachToShipment))
            .Should().BeEquivalentTo(EffectiveRoles(typeof(ShipmentsController), nameof(ShipmentsController.GetShipments)));
    }

    [Theory]
    [InlineData("Admin")]
    [InlineData("Engineer")]
    [InlineData("OfficeManager")]
    public void Quality_and_shipping_read_and_download_certificates(string role)
    {
        EffectiveRoles(typeof(CertificatesOfAnalysisController), nameof(CertificatesOfAnalysisController.List)).Should().Contain(role);
        EffectiveRoles(typeof(CertificatesOfAnalysisController), nameof(CertificatesOfAnalysisController.GetPdf)).Should().Contain(role);
    }

    [Theory]
    [InlineData("PM")]
    [InlineData("ProductionWorker")]
    [InlineData("Procurement")]
    public void Other_roles_are_refused_certificates(string role)
        => EffectiveRoles(typeof(CertificatesOfAnalysisController), nameof(CertificatesOfAnalysisController.List)).Should().NotContain(role);

    [Fact]
    public void Current_work_instructions_are_open_to_the_shop_floor()
        => EffectiveRoles(typeof(ControlledDocumentsController), nameof(ControlledDocumentsController.GetWorkInstructions))
            .Should().Contain("ProductionWorker");

    [Fact]
    public void Work_instructions_are_written_by_the_document_authors()
        => EffectiveRoles(typeof(ControlledDocumentsController), nameof(ControlledDocumentsController.CreateDocument))
            .Should().BeEquivalentTo(["Admin", "Manager", "Engineer", "ComplianceOfficer"]);

    [Theory]
    [InlineData(nameof(ProjectsController.GetProjectJobs))]
    [InlineData(nameof(ProjectsController.UnlinkJobFromWbs))]
    public void Project_job_links_follow_the_project_roles(string action)
    {
        var roles = EffectiveRoles(typeof(ProjectsController), action);

        roles.Should().BeEquivalentTo(["Admin", "Manager", "PM", "Engineer"]);
        roles.Should().NotContain(["ProductionWorker", "OfficeManager"]);
    }
}
